#pragma once
#include <array>
#include <string_view>
#include <cstdint>

//=====================================================================================================================
template<std::size_t M>
struct ShaderType
{
    std::array<std::uint8_t, M> m_binary;
    std::string_view m_kernelName;
    std::string_view m_compilerVersion;
    std::uint32_t m_codeObjectVersion;
};

//=====================================================================================================================
struct ShaderDescriptor
{
    std::string_view m_kernelName;
    std::string_view m_compilerVersion;
    std::uint32_t m_codeObjectVersion;
    const std::uint8_t* m_binary;
    std::size_t m_binarySize;

    ShaderDescriptor() 
        : m_kernelName{}
        , m_compilerVersion{}
        , m_codeObjectVersion(0)
        , m_binary(nullptr)
        , m_binarySize(0)
    {}

    template<std::size_t M>
    ShaderDescriptor(const ShaderType<M>& shader)
    {
        m_kernelName = shader.m_kernelName;
        m_compilerVersion = shader.m_compilerVersion;
        m_codeObjectVersion = shader.m_codeObjectVersion;
        m_binary = shader.m_binary.data();
        m_binarySize = M;
    }
};

//=====================================================================================================================
template<std::size_t M>
ShaderDescriptor make_shader_descriptor(const ShaderType<M>& shader)
{
    return ShaderDescriptor(shader);
}

